-- ============================================================
-- Marketplace Enhancements
-- Version: 4 (2026-06-05)
--
-- Sprint 3: Full marketplace CRUD — new status enum,
-- view tracking, featured listings, and improved filtering.
-- ============================================================

-- ── 1. Replace status CHECK with broader enum ──────────────────
--    Old: ('draft','published','withdrawn','sold')
--    New: ('active','pending_verification','sold','expired','rejected')

-- Drop the old CHECK constraint first (constraint name auto-generated by Postgres)
ALTER TABLE market_listings
  DROP CONSTRAINT IF EXISTS market_listings_status_check;

-- The SELECT policy on market_listings and the cross-table price_history
-- policy both reference status; Postgres refuses ALTER TYPE while a policy
-- depends on the column. Drop them here; the market_listings policy is
-- recreated in section 7 and the price_history policy below it.
DROP POLICY IF EXISTS "Market listings select published for all" ON market_listings;
DROP POLICY IF EXISTS "Price history readable with listing" ON price_history;

ALTER TABLE market_listings
  ALTER COLUMN status TYPE TEXT;

ALTER TABLE market_listings
  ADD CONSTRAINT market_listings_status_check
    CHECK (status IN (
      'active',
      'pending_verification',
      'sold',
      'expired',
      'rejected'
    ));

-- Migrate legacy statuses to new ones
UPDATE market_listings SET status = 'active'             WHERE status = 'published';
UPDATE market_listings SET status = 'pending_verification' WHERE status = 'draft';
UPDATE market_listings SET status = 'expired'            WHERE status = 'withdrawn';

-- Set default for new rows
ALTER TABLE market_listings
  ALTER COLUMN status SET DEFAULT 'pending_verification';

-- ── 2. Add views_count column ──────────────────────────────────
ALTER TABLE market_listings
  ADD COLUMN IF NOT EXISTS views_count INTEGER NOT NULL DEFAULT 0;

CREATE INDEX IF NOT EXISTS idx_market_views
  ON market_listings(views_count DESC);

-- ── 3. Add is_featured column ──────────────────────────────────
ALTER TABLE market_listings
  ADD COLUMN IF NOT EXISTS is_featured BOOLEAN NOT NULL DEFAULT false;

CREATE INDEX IF NOT EXISTS idx_market_featured
  ON market_listings(is_featured)
  WHERE is_featured = true;

-- ── 4. Add document_tags column (missing from initial schema) ──
ALTER TABLE market_listings
  ADD COLUMN IF NOT EXISTS document_tags TEXT[] DEFAULT '{}';

-- ── 5. Add is_seller_verified column ───────────────────────────
ALTER TABLE market_listings
  ADD COLUMN IF NOT EXISTS is_seller_verified BOOLEAN NOT NULL DEFAULT false;

-- ── 6. Performance index for filtered browse ───────────────────
CREATE INDEX IF NOT EXISTS idx_market_active_price
  ON market_listings(price_amount)
  WHERE status = 'active';

CREATE INDEX IF NOT EXISTS idx_market_active_location
  ON market_listings(location_label)
  WHERE status = 'active';

-- ── 7. Update RLS policy for new statuses ──────────────────────
--    Anyone can read active + pending; only seller can read their own.
CREATE POLICY "Market listings select active or own"
  ON market_listings FOR SELECT
  USING (
    status IN ('active', 'pending_verification')
    OR seller_id = auth.uid()
  );

-- Price history follows the new listing visibility (was 'published').
CREATE POLICY "Price history readable with listing"
  ON price_history FOR SELECT
  USING (
    listing_id IN (
      SELECT id FROM market_listings
      WHERE status IN ('active', 'pending_verification')
        OR seller_id = auth.uid()
    )
  );
